const $=id=>document.getElementById(id);let part=2,current=0,tab='answer',timer=null,remaining=60,duration=60,deadline=0;let state={done:[],notes:{}};
try{state={...state,...JSON.parse(localStorage.getItem('speaking-notebook-v1')||'{}')}}catch{}
if(!Array.isArray(state.done))state.done=[];if(!state.notes||typeof state.notes!=='object')state.notes={};
function save(){try{localStorage.setItem('speaking-notebook-v1',JSON.stringify(state));return true}catch{toast('Trình duyệt không cho lưu. Hãy sao chép ghi chú trước khi đóng.');return false}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3500)}
function stop(){clearInterval(timer);timer=null;if(window.speechSynthesis)window.speechSynthesis.cancel()}
function setPart(n){stop();part=n;current=0;tab='answer';$('search').value='';$('part2Button').classList.toggle('active',n===2);$('part1Button').classList.toggle('active',n===1);$('filter').innerHTML='<option value="">Tất cả chủ đề</option>'+[...new Set(n===2?lessons.map(l=>l.group):part1.map(l=>l[0]))].map(g=>`<option>${g}</option>`).join('');list();render()}
function list(){const q=$('search').value.toLocaleLowerCase('vi'),g=$('filter').value;const items=part===2?lessons:part1;let html='';items.forEach((l,i)=>{const title=part===2?l.title:l[1],group=part===2?l.group:l[0];if((title+' '+group+(l.topic||'')).toLocaleLowerCase('vi').includes(q)&&(!g||g===group))html+=`<button data-index="${i}" class="${current===i?'active':''}" ${current===i?'aria-current="true"':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span>${title}<small>${group}${part===2&&state.done.includes(i)?' · ✓ Đã luyện':''}</small></span></button>`});$('lessonList').innerHTML=html||'<p class="empty">Không tìm thấy bài. Thử từ khóa khác nhé.</p>';$('lessonList').querySelectorAll('button').forEach(b=>b.onclick=()=>{stop();current=Number(b.dataset.index);tab='answer';list();render()});$('progressText').textContent=state.done.length+' / 14';$('progress').value=state.done.length}
function render(){remaining=duration=60;const l=lessons[current];if(part===1){const p=part1[current];$('content').innerHTML=`<div class="tag">PART 1 · MỞ RỘNG · ${p[0]}</div><h2>${p[1]}</h2><div class="hint">Khung tự luyện: Trả lời trực tiếp → lý do → ví dụ ngắn. Khoảng 20–30 giây là gợi ý luyện tập, không phải quy định cho từng câu thi.</div><div class="answer-tools"><small>Bài mẫu tự biên soạn</small><button id="listen">▷ Nghe mẫu</button></div><div class="p1answer" lang="en">${p[2]}</div><div class="hint">${p[3]}</div><h3>Đến lượt bạn</h3><p>Giữ cách triển khai, đổi chi tiết thành trải nghiệm thật của bạn.</p><textarea class="note" id="notes" placeholder="Viết ý của bạn ở đây…" aria-label="Ghi chú Part 1"></textarea><div class="saved" id="saved">Tự lưu trên trình duyệt này.</div><button id="next" style="margin-top:15px">Câu tiếp theo →</button>`;wireNotes();$('listen').onclick=()=>speak(p[2]);$('next').onclick=()=>{stop();current=(current+1)%part1.length;list();render()};return}
$('content').innerHTML=`<div class="lesson-header"><div><div class="tag">BÀI ${String(current+1).padStart(2,'0')} / 14 · ${l.group.toUpperCase()}</div><h2>${l.title}</h2></div><button id="done">${state.done.includes(current)?'✓ Đã luyện':'Đánh dấu đã luyện'}</button></div><div class="lesson-grid"><div><section class="cue"><div class="eyebrow">YOUR CUE CARD · PART 2</div><h3 lang="en">${l.topic}</h3><div lang="en">You should say:<ul>${l.cues.map(c=>`<li>${c}</li>`).join('')}</ul></div><small>Từ tài liệu của bạn · trang ${l.page} · chuẩn hóa nhẹ cách diễn đạt</small></section><div class="tabs" role="tablist"><button data-tab="answer" role="tab">Bài mẫu</button><button data-tab="outline" role="tab">Dàn ý & cách nói</button><button data-tab="vocab" role="tab">Cụm từ hay</button><button data-tab="practice" role="tab">Tự luyện</button></div><section id="panel" class="panel" role="tabpanel"></section></div><div class="practice"><section class="side-card"><h3>◷ Một lượt luyện nói</h3><div class="mode"><button id="prep" class="active">Chuẩn bị 1′</button><button id="talk">Nói 2′</button></div><div id="clock" class="clock" aria-live="off">01:00</div><div id="clockLabel" class="clock-label">Sẵn sàng ghi nhanh từ khóa?</div><div class="timer-actions" style="margin-top:16px"><button id="start" class="primary">Bắt đầu</button><button id="reset">Làm lại</button></div><p>Hết 1 phút, tự chuyển sang 2 phút nói. Không phát âm thanh.</p></section><section class="side-card"><h3>✎ Câu chuyện của bạn</h3><textarea class="note" id="notes" placeholder="Ai / ở đâu / khi nào?&#10;Một chi tiết đáng nhớ…&#10;Mình cảm thấy thế nào?" aria-label="Ghi chú bài học"></textarea><div id="saved" class="saved">Tự lưu trên trình duyệt này.</div></section><section class="side-card"><h3>Học mẫu, đừng học thuộc.</h3><ol><li>Đọc và nắm mạch câu chuyện.</li><li>Chọn 2–3 cụm từ phù hợp.</li><li>Đổi người, nơi chốn, kỷ niệm.</li><li>Đóng mẫu và tự nói lại.</li></ol></section></div></div>`;
$('done').onclick=()=>{state.done=state.done.includes(current)?state.done.filter(i=>i!==current):[...state.done,current];save();list();$('done').textContent=state.done.includes(current)?'✓ Đã luyện':'Đánh dấu đã luyện'};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(window.speechSynthesis)window.speechSynthesis.cancel();tab=b.dataset.tab;panel()});wireNotes();$('prep').onclick=()=>setTimer(60);$('talk').onclick=()=>setTimer(120);$('reset').onclick=()=>setTimer(duration);$('start').onclick=toggleTimer;panel()}
function wireNotes(){const key=part+'-'+current;$('notes').value=state.notes[key]||'';$('notes').oninput=()=>{state.notes[key]=$('notes').value;$('saved').textContent=save()?'Đã lưu trên trình duyệt này.':'Chưa lưu được. Hãy sao chép ghi chú.'}}
function panel(){const l=lessons[current];document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',String(b.dataset.tab===tab))});if(tab==='answer'){$('panel').innerHTML=`<div class="answer-tools"><small>${l.answer.split(/\s+/).length} từ · Bài mẫu biên soạn mới<br>Học cách triển khai, không gắn band điểm.</small><div><button id="listen">▷ Nghe mẫu</button> <button id="stopVoice" aria-label="Dừng đọc">■</button></div></div><article class="answer" lang="en">${l.answer.split('\n').map(p=>`<p>${p}</p>`).join('')}</article><div class="hint"><strong>Hiểu nhanh:</strong> ${l.vi}</div><p class="saved">Giọng đọc tổng hợp của trình duyệt; chất lượng và khả năng hoạt động tùy thiết bị. Không phải giọng giám khảo.</p>`;$('listen').onclick=()=>speak(l.answer);$('stopVoice').onclick=()=>{window.speechSynthesis?.cancel();$('listen').textContent='▷ Nghe mẫu'}}else if(tab==='outline'){$('panel').innerHTML=`<h3>Dàn ý 1 phút: chỉ ghi từ khóa</h3><div class="steps">${l.notes.map((n,i)=>`<div class="step"><b>0${i+1}</b>${n}</div>`).join('')}</div><div class="hint">${l.vi}</div><h3>Điểm đáng học</h3><p>${l.tip}</p><h3>Khung có thể tái sử dụng</h3><p lang="en">I’d like to talk about… → To give you some background,… → One detail I remember is… → What made it special was…</p><p class="saved">Đây là khung gợi ý, không bắt buộc dùng đủ. Để câu chuyện dẫn đường cho từ nối.</p>`}else if(tab==='vocab'){$('panel').innerHTML=`<div class="vocab">${l.vocab.map(v=>{const [en,vi]=v.split('|');return `<div><strong lang="en">${en}</strong><span>${vi}</span></div>`}).join('')}</div><div class="hint">Tìm ý tương ứng trong bài mẫu, sau đó đặt một câu mới về bản thân. Chỉ dùng cụm từ khi hiểu nghĩa và cách kết hợp.</div><p>${l.tip}</p>`}else{$('panel').innerHTML=`<h3>Luyện nói từ chính câu chuyện của bạn</h3><p>Ghi 4 ý ngắn vào ô bên cạnh. Bắt đầu 1 phút chuẩn bị, sau đó nói trong 1–2 phút. Khi luyện, có thể hướng tới 2 phút và bấm tạm dừng nếu đã nói xong.</p><div class="hint">${l.vi} Thay các chi tiết này bằng trải nghiệm của bạn.</div><h3>Tự kiểm tra sau khi nói</h3>${['Mạch nói rõ ràng, ít dừng quá lâu để tìm ý.','Dùng từ đúng ý; biết diễn đạt lại khi thiếu từ.','Có câu đơn và câu phức phù hợp, chú ý thì của động từ.','Nói dễ nghe, chú ý trọng âm và ngắt theo cụm.'].map(s=>`<label class="check"><input type="checkbox">${s}</label>`).join('')}<p class="saved">Checklist tự soi theo 4 tiêu chí Speaking, không phải công cụ chấm band. Các dấu chọn ở đây chỉ dùng trong lượt luyện hiện tại.</p><button id="returnSample">Xem lại bài mẫu →</button>`;$('returnSample').onclick=()=>{tab='answer';panel()}}}
function speak(text){if(!('speechSynthesis'in window)){toast('Thiết bị này chưa hỗ trợ đọc văn bản. Bạn vẫn có thể đọc và tự luyện.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.88;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'))||null;u.onstart=()=>{if($('listen'))$('listen').textContent='Đang đọc…'};u.onend=()=>{if($('listen'))$('listen').textContent='▷ Nghe mẫu'};u.onerror=()=>{if($('listen'))$('listen').textContent='▷ Nghe mẫu';toast('Giọng đọc chưa sẵn sàng. Thử lại hoặc dùng phần văn bản.')};speechSynthesis.speak(u)}
function setTimer(n){clearInterval(timer);timer=null;duration=remaining=n;$('prep').classList.toggle('active',n===60);$('talk').classList.toggle('active',n===120);$('start').textContent='Bắt đầu';$('clockLabel').textContent=n===60?'Sẵn sàng ghi nhanh từ khóa?':'Nói theo dàn ý của bạn.';paintClock()}
function paintClock(){$('clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0')}
function toggleTimer(){if(timer){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));clearInterval(timer);timer=null;$('start').textContent='Tiếp tục';paintClock();return}if(remaining<=0)remaining=duration;deadline=Date.now()+remaining*1000;$('start').textContent='Tạm dừng';timer=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));paintClock();if(remaining===0){clearInterval(timer);timer=null;if(duration===60){setTimer(120);$('clockLabel').textContent='Hết giờ chuẩn bị. Bắt đầu nói nhé!';toast('Bắt đầu 2 phút nói!');toggleTimer()}else{$('start').textContent='Luyện lại';$('clockLabel').textContent='Đã hết 2 phút. Tự đánh giá lượt nói nhé.';toast('Hoàn thành lượt nói.')}}},200)}
function info(kind){$('infoBody').innerHTML=kind==='guide'?`<div class="eyebrow">MỘT BUỔI HỌC 15 PHÚT</div><h2>Đọc một lần. Kể lại theo cách của bạn.</h2><ol><li><b>5 phút đầu:</b> chọn bài, đọc cue card và mẫu. Mở “Dàn ý & cách nói” để hiểu mạch.</li><li><b>5 phút tiếp:</b> chọn 2–3 cụm từ, thay tên người, nơi chốn và kỷ niệm. Ghi từ khóa vào ô ghi chú.</li><li><b>5 phút cuối:</b> mở “Tự luyện”, dùng đồng hồ để nói rồi đối chiếu bài mẫu.</li></ol><p>Ở công ty, bạn có thể đọc yên lặng và chuẩn bị ý trước; chỉ bấm nghe khi thuận tiện. Gợi ý bắt đầu: người thân → chuyến đi → thay đổi tích cực. Đây là các câu chuyện dễ cá nhân hóa.</p><p>Ghi chú và tiến độ lưu riêng trên trình duyệt, không đồng bộ sang máy công ty. Nội dung bài học vẫn mở được bằng cùng đường dẫn và tài khoản có quyền truy cập.</p>`:`<div class="eyebrow">NGUỒN & PHƯƠNG PHÁP</div><h2>Biết mình đang học từ đâu.</h2><p>14 đề Part 2 lấy từ tài liệu “Speaking questions.pptx.pdf” (LangGo, trang 3–16). Các gợi ý được sửa nhẹ ngữ pháp nhưng giữ nội dung. 12 câu Part 1 là phần mở rộng tự biên soạn.</p><p>Bài trả lời tiếng Anh, dàn ý và giải thích tiếng Việt được viết mới cho trang này. Đây là các tình huống minh họa, không phải bài chấm chính thức hay cam kết band điểm. Tài liệu gốc ghi mức 4.0–5.0; bạn có thể chia nhỏ bài mẫu, học ý và cụm từ trước.</p><div class="source"><a href="https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-speaking" target="_blank" rel="noopener">IELTS.org · Speaking test format ↗</a><small>Đối chiếu: Part 2 có 1 phút chuẩn bị, nói tối đa 2 phút; bốn tiêu chí là độ trôi chảy và mạch lạc, từ vựng, ngữ pháp, phát âm.</small></div><div class="source"><a href="https://takeielts.britishcouncil.org/prepare/ielts-academic/speaking" target="_blank" rel="noopener">British Council · Speaking preparation ↗</a><small>Đối chiếu cách luyện: mở rộng ý bằng lý do hoặc ví dụ, ghi từ khóa khi chuẩn bị, nói tự nhiên và tránh học thuộc cả bài.</small></div><div class="source"><a href="https://takeielts.britishcouncil.org/prepare/ielts-free-practice-mock-tests/academic/speaking" target="_blank" rel="noopener">British Council · Official practice materials ↗</a><small>Tham khảo thêm bài luyện chính thức. Các bài mẫu trên trang này được biên soạn riêng, không sao chép từ nguồn này.</small></div><p>Tra cứu ngày 16/11/2026. Trang không thu âm và không chấm điểm tự động. Giọng nghe là giọng tổng hợp có sẵn trên thiết bị.</p>`;$('info').showModal()}
$('part2Button').onclick=()=>setPart(2);$('part1Button').onclick=()=>setPart(1);$('search').oninput=list;$('filter').onchange=list;$('guideButton').onclick=()=>info('guide');$('sourceButton').onclick=()=>info('sources');$('closeInfo').onclick=()=>$('info').close();window.addEventListener('pagehide',stop);setPart(2);
